<?php
namespace App\Http\Controllers;
use App\Models\{Apprentice,ApprenticeSetupDraft68 as Draft,ProgrammeSetupTemplate68 as Template,Employer,User,TutorGroup};
use App\Support\{GuidedSetup68 as Setup,Rpl68,LearningAccess,DirectoryCatalog};
use Illuminate\Http\Request;
class GuidedSetup68Controller extends Controller {
 private function allow(Request $r):void {abort_unless($r->user()?->can('create',Apprentice::class),403);}
 public function index(Request $r){$this->allow($r);return response()->view('setup68.index',['drafts'=>Draft::orderByDesc('updated_at')->paginate(20)])->header('Cache-Control','no-store, private');}
 public function create(Request $r){$this->allow($r);$d=Setup::start($r->user(),(int)$r->session()->get('auth_version'));return to_route('setup68.show',[$d,1]);}
 public function show(Request $r,Draft $draft,int $step=1){$this->allow($r);abort_unless(isset(Setup::STEPS[$step]),404);return $this->page($r,$draft,$step);}
 private function page(Request $r,Draft $draft,int $step,array $extra=[]){$p=$draft->payload;$review=Setup::review($draft);$t=$review['template'];$search=mb_strtolower(trim((string)$r->query('search','')));$block=$r->integer('block');$adjusted=$r->boolean('adjusted');$ksbs=$t?$t->template['ksbs']:[];$ksbs=array_values(array_filter($ksbs,fn($k)=>($search===''||str_contains(mb_strtolower($k['code'].' '.$k['description']),$search))&&(!$block||in_array($block,$k['blocks'],true))&&(!$adjusted||($p['rpl']['adjustments'][$k['code']]??0)>0)));
  $needle=mb_strtolower(trim((string)$r->query('employer_search','')));$employers=$needle!==''?Employer::where('active',true)->where(fn($q)=>$q->whereRaw("LOWER(name) LIKE ? ESCAPE '!'",['%'.str_replace(['!','%','_'],['!!','!%','!_'],$needle).'%'])->orWhere('reference',$needle))->limit(30)->get():collect();if(!empty($p['employer']['id']))$employers=$employers->merge(Employer::whereKey($p['employer']['id'])->get())->unique('id');
  return response()->view('setup68.wizard',[...compact('draft','step','p','review','ksbs','employers'), 'templates'=>Template::where('active',true)->get()->filter(fn($x)=>Setup::template(['programme'=>['template_id'=>$x->id]])!==null),'markers'=>json_decode(file_get_contents(resource_path('data/inclusion-markers.json')),true),'tutors'=>User::where('role','tutor')->where('active',true)->get(),'groups'=>TutorGroup::where('active',true)->get(),'staffOptions'=>collect(['mentor_id'=>'mentor','careers_adviser_id'=>'careers_adviser','maths_tutor_id'=>'maths_tutor','english_tutor_id'=>'english_tutor'])->mapWithKeys(fn($role,$field)=>[$field=>DirectoryCatalog::options(\App\Support\StaffDuties::query(User::query(),$role))])->all(),...$extra])->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');
 }
 public function save(Request $r,Draft $draft,int $step){$this->allow($r);$r->validate(['version'=>['required','integer','min:1'],'next'=>['nullable','integer','between:1,6']]);$input=$r->input('data',$step===5&&$r->has('employer_search')?($draft->payload['employer']??[]):[]);abort_unless(is_array($input),422);
  if($step===4){$current=$draft->payload['rpl']??[];$action=$r->input('action','save');if($action==='none')$input=['mode'=>'none'];
   elseif(in_array($action,['batch_preview','batch_apply'],true)){
    $v=$r->validate(['codes'=>['required','array','min:1','max:300'],'codes.*'=>['required','string'],'percent'=>['required','integer','between:0,100']]);if($v['percent']%10!==0)Rpl68::fail('Choose a 10-percentage-point reduction.');abort_if($draft->version!==$r->integer('version'),409,'Draft changed. Reload the KSB list.');$t=Setup::template($draft->payload);if(!$t)Rpl68::fail('Select a programme first.');$codes=array_values(array_unique($v['codes']));if(array_diff($codes,array_column($t->template['ksbs'],'code')))Rpl68::fail('Select KSBs from this programme only.');$batch=['codes'=>$codes,'percent'=>(int)$v['percent'],'binding'=>Rpl68::hash([$draft->version,$codes,(int)$v['percent'],$t->source_hash])];
    if($action==='batch_preview'){$proposed=$current;foreach($codes as $code)$proposed['adjustments'][$code]=(int)$v['percent'];return $this->page($r,$draft,4,['batch'=>$batch,'batch_calculation'=>Rpl68::calculate($t->template,$proposed)]);}if($r->input('binding')!==$batch['binding'])Rpl68::fail('Preview these KSB changes again.');$input=[...$current,'mode'=>'applies','remaining_confirmed'=>false];foreach($codes as $code){if($v['percent']===0||$v['percent']==='0')unset($input['adjustments'][$code]);else $input['adjustments'][$code]=(int)$v['percent'];}
   }else{$input=[...$current,...$input,'remaining_confirmed'=>$r->boolean('data.remaining_confirmed')];}
  }
  $d=Setup::save($r->user(),(int)$r->session()->get('auth_version'),$draft,$r->integer('version'),$step,$input);$next=$r->integer('next')?:$step;if($step===1&&Setup::matches($d->payload['details']??[],$d->apprentice_id))$next=1;return to_route('setup68.show',[$d,$next,...($step===5&&$r->has('employer_search')?['employer_search'=>mb_substr((string)$r->input('employer_search'),0,100)]:[])])->with('status',$next===1&&$step===1?'Draft saved. Review any possible existing record before continuing.':'Draft saved.');
 }
 public function submit(Request $r,Draft $draft){$this->allow($r);$r->validate(['version'=>['required','integer'],'confirmed'=>['accepted']]);$d=Setup::submit($r->user(),(int)$r->session()->get('auth_version'),$draft,$r->integer('version'));return to_route('setup68.show',[$d,6])->with('status','Ready for independent plan review in this same setup record.');}
 public function confirm(Request $r,Draft $draft){$this->allow($r);$r->validate(['version'=>['required','integer'],'confirmed'=>['accepted']]);$d=Setup::confirm($r->user(),(int)$r->session()->get('auth_version'),$draft,$r->integer('version'));return to_route('setup68.show',[$d,6])->with('status','Setup complete. The approved training plan and OTJ target are now linked to the apprentice.');}
 public function reopen(Request $r,Draft $draft){$this->allow($r);$v=$r->validate(['version'=>['required','integer'],'reason'=>['required','string','max:1000']]);$d=Setup::reopen($r->user(),(int)$r->session()->get('auth_version'),$draft,$v['version'],$v['reason']);return to_route('setup68.show',[$d,4])->with('status','Same RPL record reopened. The current approved plan stays active until the correction is independently confirmed.');}
}
